from pathlib import Path
import json,sqlite3
w=Path(__file__).resolve().parent
c=sqlite3.connect('file:'+str(w/'input/index.sqlite3')+'?mode=ro',uri=True);c.row_factory=sqlite3.Row
sources={}
for row in c.execute('SELECT * FROM segments'):
 d=dict(row);sources[(d['path'],d['anchor'])]=d
r=json.loads((w/'input/report-ledger.json').read_text())
paths={'P':'input/sources/procurement-standard.docx.md','V':'input/sources/revision-amendment.pdf.md','A':'input/sources/approval-attestations.scan.pdf.md','D':'input/sources/delegation-notice.md','L':'input/sources/purchase-register.md','X':'input/sources/exception-file.md','F':'input/sources/reconciliation-correspondence.md'}
def ev(marker):
 prefix=marker[0];n=int(marker[1:]);anchor=f'docx-p-{n*2+2:04d}' if prefix=='P' else f'pdf-page-{n+1:04d}' if prefix in 'VA' else marker
 anchor = anchor + '-reviewed-0001' if prefix == 'A' else anchor
 d=sources[(paths[prefix],anchor)];loc=json.loads(d['locator'])
 coord={k:v for k,v in loc.items() if k in ('kind','page','original','original_sha256','xml_member','xml_path','paragraph_index','member','path')}
 return {'path':paths[prefix],'anchor':anchor,'quote':d['quote'],'source_marker':marker,'original_coordinate':coord}
def pr(t,target,relation):return {'module':'Audit','theorem':'Audit.'+t,'target':target,'relation':relation}
f=[]
def add(n,question,markers,rules,reason,state,arg,formal,proofs,limits,recommendation,assumptions=None):
 k=f'C06-{n:02d}'
 f.append({'claim_id':k,'report_anchor':k,'report_quote':r[k],'question':question,'evidence':[ev(m) for m in markers],'rules':rules,'assumptions':assumptions if assumptions is not None else ['Use the supplied fictional HPS clauses and exact documentary inputs within their stated May-June 2029 scope; source authenticity beyond explicit stipulations is not independently established.','Source-to-symbol transcription is scoped to the cited paragraphs/pages and actual extraction/visual reviews; independently checked numeric/date conversions are retained in arithmetic-check.md.'],'reasoning':[str(i+1)+'. '+x for i,x in enumerate(reason)],'semantic_state':state,'argument_status':arg,'formal_status':formal,'proofs':proofs,'limits':limits,'recommendation':recommendation})
add(1,'Do P-11 and P-12 avoid competition merely because each order is individually below EUR 25,000, once the inclusive 30-date aggregation rule and prior knowledge of the combined requirement are applied?', ['P02','P03','L01','L02','F04','V01'],['P03 aggregates the same project, legal supplier and single operational requirement within first commitment date through first+29 dates; known full requirements are threshold-tested together before first commitment.','P02 requires competition at an inclusive threshold unless an established exception applies. Accepted June 1 receipt invokes revision 2 under V01.'],['The individual amounts EUR 12,400 and EUR 12,600 are each below EUR 25,000; that premise is true.','L02 establishes one TIDE-4 sensor rack, the same legal supplier and both halves known in the May 28 specification. F04 confirms differing pallets/cost centers are logistical/accounting labels, not independent requirements.','Commitments June 3 and June 20 differ by 17 dates; the latter is window day 18 and lies inside the inclusive thirty-date window.','P03 therefore applies the combined EUR 25,000 value before the first commitment. Equality triggers revision 2 competition; L02 records no certificate, emergency declaration or other exception.','The no-competition conclusion is refuted because it tests the wrong unit of purchase, despite the true individual amounts.'],'refuted','invalid_inference','refuted',[pr('claim01','Audit.rackAggregates = true ∧ Audit.rackKnownBeforeFirst = true ∧ Audit.competitionRequired 2 Audit.rackCents = true ∧ (1240000 : Nat) < 2500000 ∧ (1260000 : Nat) < 2500000','refutes')],['The aggregation result is specific to this documented pair and its known shared requirement; supplier similarity or merely serving one laboratory would not suffice.'],'Replace the conclusion with an inclusive EUR 25,000 aggregate competition obligation, and record the missing covered certificate/exception separately from valid spending approvals.')
add(2,'Is the combined normalized P-11/P-12 value exactly EUR 25,000.00 under P04 without adding, subtracting or rerounding undocumented amounts?', ['L01','L02','P04'],['L01 defines the stated normalized values as including unavoidable charges, excluding recoverable VAT and already finally rounded. Sum the two stated normalized values once.'],['L02 provides normalized EUR 12,400.00 and EUR 12,600.00.','In integer cents, 1,240,000 + 1,260,000 = 2,500,000, exactly EUR 25,000.00. No extra fee, rebate or conversion is supplied for these amounts.','The checked arithmetic supports the exact combined-value assertion; aggregation applicability is independently explained in C06-01.'],'supported','sufficient','proved',[pr('claim02','Audit.rackCents = 2500000','supports')],['The calculation does not independently authenticate prices or certify compliance.'],'Retain the exact amount and normalized-value scope.')
add(3,'Does P-13 exact USD consideration at its fixed contractual rate reach the revision 2 inclusive competition threshold after the required single final cent rounding?', ['P02','P04','V01','V05','L03','F01'],['P04 requires exact rational conversion followed by a single nearest-cent rounding, ties upward; threshold comparison uses that normalized value.','V05 fixes USD/EUR at 0.900000; June 4 receipt uses revision 2 and its inclusive EUR 25,000 threshold.'],['V05 fixes USD 27,777.775 with no extra freight, rebate or separately included VAT. The original PDF page 6 was visually inspected.','The exact rational multiplication 27,777.775 × 0.9 gives EUR 24,999.9975, represented as 249999975 ten-thousandths.','Single final rounding gives 2,500,000 cents, EUR 25,000.00. This equals the inclusive revision 2 threshold and requires competition.','F01 independently corroborates that arithmetic; L03 also records that the required complete competition certificate and director approval actually exist.'],'supported','sufficient','proved',[pr('claim03','Audit.p13Exact = 249999975 ∧ Audit.p13Cents = 2500000 ∧ Audit.competitionRequired 2 Audit.p13Cents = true','supports')],['This proves threshold classification after the sourced normalization, not a general theorem about arbitrary exchange rates or substantive procurement quality.'],'Retain and show both the exact intermediate value and the final normalized value.')
add(4,'Can P-13 be classified below threshold using exact EUR 24,999.9975 before final rounding, when P04 prescribes threshold comparison after normalization?', ['P02','P04','V05','L03','F01'],['P04 explicitly forbids testing the unrounded result against the threshold. P02 equality after normalization triggers competition.'],['The report accurately states the unrounded rational amount: EUR 24,999.9975 is less than EUR 25,000.','But that amount is not the prescribed threshold input. Final nearest-cent rounding produces EUR 25,000.00.','The normalized result is not below the threshold, so the report conclusion is false and its comparison uses the wrong calculation stage. F01 explicitly warns against that step.'],'refuted','invalid_inference','refuted',[pr('claim04','Audit.p13Exact < 250000000 ∧ ¬ (Audit.p13Cents < 2500000)','refutes')],['The exact pre-rounding number itself is not refuted; only its use to establish below-threshold status and that resulting status fail.'],'Replace the conclusion with threshold equality after required rounding.')
add(5,'Does EUR 24,999.994 for the independent P-14 requirement round to EUR 25,000.00 and trigger revision 2 competition?', ['P02','P04','V01','L03','F02'],['Nearest-cent half-up rounding changes 24,999.994 to 24,999.99 because the remainder after cents is 0.004, below a half-cent. Revision 2 threshold is inclusive EUR 25,000.'],['L03 states exact unrounded EUR 24,999.994, no other consideration/VAT/rebates and no aggregating requirement; accepted June 5 receipt invokes revision 2.','The correct final rounding yields 2,499,999 cents, corroborated explicitly by F02. It does not yield 2,500,000 cents.','The normalized value is one cent below threshold, so P-14 does not require competition under P02. Both the stated rounding and its obligation conclusion fail.'],'refuted','invalid_inference','refuted',[pr('claim05','Audit.p14Cents = 2499999 ∧ Audit.p14Cents ≠ 2500000 ∧ Audit.competitionRequired 2 Audit.p14Cents = false','refutes')],['A valid pre-commitment approval remains necessary even when competition is not required; L03 supplies it.'],'Correct the normalized value to EUR 24,999.99 and remove the asserted competition obligation.')
add(6,'Was Dana Cole P-15 approval valid at the inclusive delegation expiry, despite commitment one minute later?', ['P05','D01','D02','D03','L01','L04'],['P05/D01 measure category, amount and authority time at approval; the delegation expiry is inclusive and later commitment does not invalidate prior approval. Approval must strictly precede commitment.'],['P-15 is independent laboratory consumables for EUR 14,900, within Dana covered category and inclusive EUR 15,000 ceiling.','Approval occurred June 15 at exactly 17:00, the last authorized minute; D02 records no delegation change and D03 confirms exact-minute semantics.','Commitment at 17:01 is later than approval. Authority need not persist until commitment under the explicit rule.','All applicable approval conditions hold, so the report assertion and its qualification are supported.'],'supported','sufficient','proved',[pr('claim06','Audit.delegatedApproval true 1490000 21180 21181 = true ∧ (21180 : Nat) < 21181','supports')],['This validates the P-15 approval event only, not a general authority extension after 17:00 or an emergency waiver.'],'Retain the conclusion and identify approval time as the controlling authority instant.')
add(7,'Did P-16 approval at June 15 17:01 satisfy Dana delegation merely because the amount exactly met her EUR 15,000 ceiling?', ['P05','D01','D02','D03','D04','L01','L04'],['Value authority and time authority are conjunctive. D03 expressly excludes 17:01 or later approvals despite an inclusive monetary ceiling. L04 and L01 establish absence of an alternative approval within complete coverage.'],['P-16 laboratory-consumables category and EUR 15,000 value satisfy Dana category and monetary conditions.','Her actual approval is at 17:01, one minute after inclusive 17:00 expiry. D02 records no extension or substitute authority.','Approval before 17:10 commitment cannot cure expired authority at the approval instant. The complete transaction register expressly records no director or alternative delegate approval and no retroactive ratification.','The reported valid approval is refuted: a true monetary premise does not satisfy the independently failed time condition.'],'refuted','invalid_inference','refuted',[pr('claim07','(1500000 : Nat) ≤ 1500000 ∧ Audit.delegatedApproval true 1500000 21181 21190 = false','refutes')],['The conclusion uses explicit covered event absence and exact timestamps; it is not inferred merely from a missing signature page.'],'Record invalid delegated approval and identify the missing valid alternative approval, without treating the monetary ceiling itself as exceeded.')
add(8,'Does R-17 unchanged original requirement switch to revision 2 because a clerical amendment and commitment occurred after June 1?', ['V01','V02','V03','L05'],['V01 retains revision 1 for original scope accepted before June 1 00:00. V02 applies revision 2 only to additional independently priced requirements introduced by material changes; clerical contact/billing corrections are not material.'],['R-17 receipt is May 31 23:59, exactly one minute before transition.','V03 explicitly says the June 3 amendment changed contact/cost-center spelling only; specification, supplier, price, quantity and functional requirement remained unchanged.','Neither June 10 commitment nor a current-version dashboard label changes the retained revision. No additional requirement invokes V02.','Revision 1 governs the original requirement, directly contradicting the revision 2 claim and both stated switching reasons.'],'refuted','invalid_inference','refuted',[pr('claim08','Audit.revision (-1) = 1 ∧ Audit.revision (-1) ≠ 2','refutes')],['The result is about unchanged original scope; a genuine separately priced added requirement could require separate V02 analysis.'],'Use revision 1 for R-17 and preserve the distinction between clerical and material amendments.')
add(9,'Does R-17 require competition at normalized EUR 22,500 under retained revision 1, and does complete coverage establish no certificate or exception?', ['P02','V01','V03','L01','L05'],['Revision 1 inclusive threshold is EUR 20,000. L01 completeness covers R-17 competitive certificates and exception determinations; explicit none is event absence in that coverage.'],['R-17 pre-boundary receipt and unchanged scope retain revision 1. EUR 22,500 exceeds EUR 20,000.','L05 expressly records competitive-solicitation certificate: none and exception determination: none for R-17.','The valid June 9 director approval satisfies a separate requirement, but cannot substitute for competition or a fully established exception. Both report components are supported.'],'supported','sufficient','proved',[pr('claim09','Audit.competitionRequired (Audit.revision (-1)) 2250000 = true ∧ Audit.r17Certificate = false ∧ Audit.r17Exception = false','supports')],['Negative event conclusions extend only to the named complete R-17 domain and May-June period; they do not create completeness for E-20/P-21 or payment.'],'Retain the finding and distinguish its competition failure from its valid spending approval.')
add(10,'Does R-18 original requirement use revision 1 merely because its EUR 22,500 exceeds that older threshold, despite exact boundary receipt?', ['P02','V01','V04','L05'],['V01 assigns accepted receipt at the exact boundary to revision 2. The applicable threshold must be selected before comparing the amount.'],['V04 gives exact receipt June 1 00:00, not a rounded earlier time, and no aggregation relationship or material added requirement.','Thus revision 2 applies. EUR 22,500 is below its EUR 25,000 threshold, although above revision 1 EUR 20,000.','The comparison with the older threshold is numerically true but normatively inapplicable. R-18 does not require competition under the supplied standard.'],'refuted','invalid_inference','refuted',[pr('claim10','Audit.revision 0 = 2 ∧ Audit.competitionRequired (Audit.revision 0) 2250000 = false ∧ (2000000 : Nat) ≤ 2250000','refutes')],['Identical values and commitment dates do not make R-17 and R-18 share a revision; their accepted receipt timestamps differ across the explicit boundary.'],'Apply revision 2 and remove the asserted competition obligation for R-18.')
add(11,'Did actual E-19 satisfy every urgent-safety exception condition, including a review at the inclusive forty-eight-hour limit after commitment?', ['P05','P06','L05','X01','X02'],['P06 requires confirmed active safety incident, director written declaration strictly before commitment, and director review in the inclusive interval from commitment to +48 hours; order approval remains a separate requirement.'],['X01 establishes confirmed active reagent-overheating safety incident S-19 and identifies E-19 as the immediate control; it is not mere delay inconvenience.','X02 records EM-19 at June 22 09:45 expressly making both declaration and order approval and identifying incident, requirement, supplier and EUR 31,000. Commitment is 10:00, so declaration and approval precede it by 15 minutes.','Review at June 24 10:00 is 2880 minutes after commitment, exactly forty-eight hours. P06 expressly includes equality and measures from commitment, not earlier declaration.','Every exception condition holds and separate approval is explicit. The claimed exception and endpoint timing are supported.'],'supported','sufficient','proved',[pr('claim11','Audit.e19Emergency = true ∧ (33720 - 30840 : Nat) = 2880 ∧ Audit.e19Approval = true','supports')],['The exception waives competition only; it neither establishes prudence nor excuses unrelated earlier sensor-rack purchases.'],'Retain with all three conjuncts and the express separate order-approval decision.')
add(12,'Under P06, would confirmed E-19 urgency alone satisfy the exception in the counterfactual absence of both director declaration and retrospective review?', ['P06','X01','X02'],['P06 requires all three conditions and explicitly states a genuine incident alone is insufficient. A counterfactual omitting required conjuncts cannot inherit the actual complete exception.'],['Actual X01 confirms urgency, and actual X02 supplies the other two conditions.','The report asks whether urgency would suffice without those conditions. P06 expressly denies that sufficiency.','In the scoped hypothetical model, incident=true but declaration and review absent yields exception=false. This is a counterexample to urgency-alone sufficiency, and direct refutation of the report counterfactual rule claim.'],'refuted','invalid_inference','refuted',[pr('claim12','Audit.emergency true none none 30840 = false','refutes')],['The theorem does not assert that actual E-19 lacked declaration/review or failed the exception; actual E-19 is supported in C06-11.'],'Replace the counterfactual with the conjunctive rule: urgency is necessary here but insufficient alone.')
add(13,'Does sole current warranty-certified vendor status establish E-20 proprietary-compatibility exception without the governing Annex Q test, certification rules and final determination?', ['P07','V06','X03','X04','X05'],['P07 reserves the definition of compatibility, certification and substitutes to Annex Q. Missing Annex Q does not mean conditions are waived, satisfied or impossible. Spending approval is distinct from a competition exception.'],['X03 supports the factual premise that Pelican is the sole currently warranty-certified vendor and records a proposed exception only.','X04 limits the warranty evidence to its current certification list and says the rival was not assessed for warranty eligibility. Neither source has authority to define Annex Q.','V06/X05 establish that Annex Q and a director-adopted interpretation are not supplied; no final Annex Q determination is in the file.','A warranty-only reading and physical-interchangeability reading give opposite only-compatible-source answers on the known evidence. The auxiliary theorem demonstrates definition dependence, not actual annex content or complete exception qualification.','The positive qualification claim has insufficient support. It is not disproved merely because Annex Q is missing.'],'undetermined','insufficient_support','auxiliary',[pr('compatibilityAlternatives','Audit.onlyCompatible .warranty true true = true ∧ Audit.onlyCompatible .physical true true = false','auxiliary')],['The two candidate tests illustrate missing normative meaning; neither is asserted as the operative Annex Q, and other required certification steps may exist. No actual exception verdict follows.'],'Obtain Annex Q, any adopted interpretation and the final scoped exception determination before claiming qualification.',['Treat X03/X04 as scoped technical/certification evidence and V06/X05 as package-level inventory only. Alternative tests are hypothetical, not invented operative rules.'])
add(14,'Does the rival connector passing mechanical-fit and electrical bench tests rule out E-20 proprietary exception without knowing Annex Q compatibility criteria?', ['P07','V06','X03','X04','X05'],['The governing compatibility test comes from Annex Q, not automatically from a physical/electrical bench test. Different scoped technical propositions are not contradictory testimony about a single defined criterion.'],['The rival bench-test success is affirmative evidence of mechanical/electrical behavior, but X04 excludes saltwater durability and warranty acceptance.','Pelican sole current certification and rival bench success can both be true. Their coexistence does not settle which concept Annex Q requires.','Under a hypothetical warranty criterion the known evidence can support sole-source status; under a physical criterion it does not. Neither reading is established by the missing annex.','Therefore the categorical cannot-qualify conclusion is also insufficiently supported; missing definition blocks both blanket qualification and blanket disqualification.'],'undetermined','insufficient_support','auxiliary',[pr('compatibilityAlternatives','Audit.onlyCompatible .warranty true true = true ∧ Audit.onlyCompatible .physical true true = false','auxiliary')],['This is missing normative information, not a conflict between mutually negating witnesses and not proof that the exception is true. Bench success alone does not establish every relevant technical dimension.'],'State the evidence under its actual test scope and defer the categorical exception verdict until Annex Q and a final determination are available.',['No physical or warranty test is silently chosen as controlling; X04 limitations are retained.'])
add(15,'What establishes or denies the exact P-21 director approval event at June 27 10:00 UTC, given authentic but unreconciled signed attestations and exclusion from L01 completeness?', ['A01','A02','A03','P08','L01'],['P08 preserves conflicting signed statements until authorized resolution. A03 stipulates signature authenticity but no priority, retraction or adjudication; L01 explicitly excludes P-21.'],['Supporting testimony: visually checked A01 has Mara Voss affirm that the director granted written P-21 order approval at 10:00 before 10:30 commitment and that she examined the document.','Countertestimony: visually checked A02 has Tomas Reed deny any director approval at/before 11:00 and explicitly deny the reported 10:00 event. This is not merely failure to find an attachment.','A03 fixes identical order/day and authentic signatures; no source precedence or resolving document is supplied. The record cannot be reconciled by shifting date, person, order or timezone.','Both support and direct denial remain attributable evidence. The auxiliary model records the opposing testimonies and does not assert both event propositions as world facts. Actual approval is unresolved.'],'both','disputed','auxiliary',[pr('claim15Conflict','Audit.maraAffirms = true ∧ Audit.tomasDenies = true','auxiliary')],['Signature authenticity is stipulated by A03 rather than cryptographically tested by this audit, and does not establish statement truth. Manual visual comparison resolves OCR transcription issues but not the substantive witness disagreement.'],'Display both named accounts and obtain the original approval instrument or an authorized adjudication; do not choose a witness by issue time or signature alone.',['Actual scan pages 2-4 were visually inspected; corrected material characters must be preserved through the controlled transcription record, not silently altered in raw OCR.','Treat signed statements as testimony only; do not extend L01 closed coverage to P-21.'])
add(16,'Do a signed P-21 invoice and delivery acceptance establish that Harbor paid, when settlement evidence and bank reconciliation were not supplied?', ['P01','A04','F03','L01'],['P01 distinguishes payment request, delivery acceptance and payment; none automatically establishes another event. L01 explicitly excludes payment history. Missing payment evidence is not a negative settlement fact.'],['F03 establishes a signed invoice requesting EUR 8,000 and a warehouse acceptance confirming delivery. Neither states settlement.','F03 explicitly says the bank reconciliation was not transferred and finance cannot confirm or deny payment. A04 confirms no payment entry, bank statement or payment authorization in the scan packet.','The proposed payment inference lacks the settlement event premise. A paid and an unpaid hypothetical history both preserve the supplied invoice and delivery facts.','The auxiliary countermodel shows failure of entailment. The actual payment claim is undetermined, not refuted by invented nonpayment evidence.'],'undetermined','insufficient_support','auxiliary',[pr('claim16Alternatives','Audit.possiblePaid.signedInvoice = true ∧ Audit.possibleUnpaid.signedInvoice = true ∧ Audit.possiblePaid.deliveryAccepted = true ∧ Audit.possibleUnpaid.deliveryAccepted = true ∧ Audit.possiblePaid.paid = true ∧ Audit.possibleUnpaid.paid = false','auxiliary')],['No bank record was inspected and no historical payment/nonpayment conclusion is proved. Resolving the separate approval conflict would still not establish settlement.'],'Replace the asserted payment with confirmed invoice/delivery facts and request settlement or bank-reconciliation evidence.',['The observed invoice and acceptance are accepted as documentary facts; possible paid/unpaid worlds are explanatory countermodels, not actual event findings.'])
add(17,'Did every one of the nine explicitly L01-covered purchases satisfy both its applicable competition limb and valid pre-commitment approval limb?', ['P02','P03','P05','P08','V01','L01','L02','L03','L04','L05','D01','D02','D03'],['P08 defines compliance conjunctively: satisfy applicable competition or a fully established exception, and possess valid pre-commitment approval. A universal claim fails on a single in-scope actual counterexample.','L01 complete domain is exactly P-11/P-12/P-13/P-14/P-15/P-16/R-17/R-18/E-19; it excludes E-20/P-21/payment.'],['P-16 belongs to L01 and has Dana approval one minute after expiry, with no director/alternative approval in complete coverage. Therefore its valid-approval limb fails even though it is below competition threshold.','P-11/P-12 also belong to L01: their known aggregate equals revision 2 threshold, and L02 explicitly records no competition certificate or exception, despite valid director approvals.','R-17 independently requires revision 1 competition with no covered certificate or exception.','The exact universal claim is refuted by P-16 alone; the model proves both its membership and failure, then the negation of universal compliance. It also verifies P-11 as a separate competition-limb counterexample.','Unresolved E-20 compatibility and P-21 testimony are unnecessary to this refutation and are not incorrectly placed inside L01 coverage.'],'refuted','invalid_inference','refuted',[pr('claim17Witnesses','Audit.CoveredPurchase.p16 ∈ Audit.covered ∧ Audit.approvalValid .p16 = false ∧ Audit.compliant .p16 = false ∧ Audit.CoveredPurchase.p11 ∈ Audit.covered ∧ Audit.required .p11 = true ∧ Audit.rackCertificate = false ∧ Audit.rackException = false ∧ Audit.compliant .p11 = false','refutes'),pr('claim17UniversalFalse','¬ (∀ p, p ∈ Audit.covered → Audit.compliant p = true)','refutes')],['This disproves all-covered-purchase compliance, not compliance of every individual purchase. The model does not authenticate records or generalize completeness to other orders/events.'],'Replace the blanket statement with purchase-specific results, explicitly naming P-16 approval failure and the P-11/P-12 and R-17 competition failures.')
add(18,'Can the supplied standard and attributed retrospective comment establish that the emergency pump purchase was prudent and commercially elegant under a defined operational criterion?', ['P08','F05','P06','X02'],['P08 explicitly supplies no prudence or commercial-elegance metric. Compliance and a timely emergency process do not themselves define qualitative merit.'],['F05 attributes the description to an internal retrospective opinion and supplies no decision model, risk utility scale, price benchmark or evaluative definition.','P08 separates these evaluations from objective threshold/timing calculations. Actual E-19 exception compliance does not entail either adjective.','The two qualitative components remain outside formal assessment under the supplied mandate; no proof of their truth or falsity is manufactured.'],'not_applicable','nonformal','not_attempted',[],['This is an undefined evaluative criterion, not evidence that the purchase was imprudent or commercially inelegant. The sourced management opinion can be reported as attributed opinion.'],'Attribute the opinion explicitly or agree a measurable decision criterion and supporting evidence before making a formal evaluation.',['No unstated utility model, market benchmark or procurement custom is introduced.'])
(w/'findings.json').write_text(json.dumps(f,indent=2,ensure_ascii=False)+'\n')
print('Wrote',len(f),'findings')
